import toast from 'react-hot-toast';

import { validateImportData } from '@/utils/security/import-validation';
import { MAX_FILE_SIZE_BYTES } from '@/constants';

// Mock react-hot-toast module
jest.mock('react-hot-toast', () => ({
  __esModule: true,
  default: {
    error: jest.fn(),
    success: jest.fn(),
  },
}));

// Get mocked toast functions for assertions
const mockToast = toast as jest.Mocked<typeof toast>;

describe('JSON Import Validation Security', () => {
  beforeEach(() => {
    // Clear all mocks before each test
    jest.clearAllMocks();
  });

  describe('Positive Tests - Valid JSON should pass', () => {
    test('accepts valid conversation export format V1 (array)', () => {
      const validJson = JSON.stringify([
        {
          id: 1,
          name: 'Test Conversation',
          messages: [
            { role: 'user', content: 'Hello' },
            { role: 'assistant', content: 'Hi there!' },
          ],
        },
      ]);

      const result = validateImportData(validJson);
      expect(result).not.toBeNull();
      expect(Array.isArray(result)).toBe(true);
      if (Array.isArray(result)) {
        expect(result[0].name).toBe('Test Conversation');
      }
      // Valid data should not trigger error toasts
      expect(mockToast.error).not.toHaveBeenCalled();
    });

    test('accepts valid conversation export format V2+ (object)', () => {
      const validJson = JSON.stringify({
        version: 4,
        history: [
          {
            id: 'conv-1',
            name: 'Chat',
            messages: [],
            folderId: null,
          },
        ],
        folders: [],
        prompts: [],
      });

      const result = validateImportData(validJson);
      expect(result).not.toBeNull();
      if (result && !Array.isArray(result) && 'version' in result) {
        expect(result.version).toBe(4);
        expect(Array.isArray(result.history)).toBe(true);
      }
      // Valid data should not trigger error toasts
      expect(mockToast.error).not.toHaveBeenCalled();
    });

    test('accepts empty valid structures', () => {
      const emptyArray = JSON.stringify([]);
      const emptyObject = JSON.stringify({ history: [], folders: [] });

      expect(validateImportData(emptyArray)).not.toBeNull();
      expect(validateImportData(emptyObject)).not.toBeNull();
      // Valid data should not trigger error toasts
      expect(mockToast.error).not.toHaveBeenCalled();
    });
  });

  describe('Negative Tests - Invalid/malicious JSON should be blocked', () => {
    test('blocks prototype pollution attempts', () => {
      const maliciousJson = JSON.stringify({
        __proto__: { isAdmin: true },
        constructor: { prototype: { isEvil: true } },
        history: [
          {
            id: 'conv-1',
            name: 'Test Conversation',
            messages: [],
          },
        ],
        folders: [],
      });

      const result = validateImportData(maliciousJson);
      expect(result).not.toBeNull();
      // Dangerous payloads should be sanitized - the malicious content should not be there
      const proto = Object.getPrototypeOf(result!);
      expect(proto).not.toHaveProperty('isAdmin');

      // The constructor property exists naturally, but shouldn't contain our malicious payload
      expect(result!.constructor).not.toEqual({ prototype: { isEvil: true } });
      // Safe data should remain
      if (result && !Array.isArray(result) && 'history' in result) {
        expect(result.history).toBeDefined();
      }
    });

    test('blocks malformed JSON', () => {
      const malformedJsons = [
        '{"invalid": json}',
        '{"incomplete": ',
        'not json at all',
        '{"trailing": "comma",}',
      ];

      malformedJsons.forEach((json) => {
        expect(validateImportData(json)).toBeNull();
      });

      // Should call toast.error for each malformed JSON (excluding empty string which fails basic validation)
      expect(mockToast.error).toHaveBeenCalledWith('Invalid JSON format');
      expect(mockToast.error).toHaveBeenCalledTimes(malformedJsons.length);

      // Test empty string separately - it fails basic validation, no toast call
      expect(validateImportData('')).toBeNull();
    });

    test('blocks non-object/non-array data', () => {
      const invalidData = [
        JSON.stringify('just a string'),
        JSON.stringify(123),
        JSON.stringify(true),
        JSON.stringify(null),
      ];

      invalidData.forEach((json) => {
        expect(validateImportData(json)).toBeNull();
      });

      // Should call toast.error for each invalid data type
      expect(mockToast.error).toHaveBeenCalledWith(
        'Import data must be a valid object',
      );
      expect(mockToast.error).toHaveBeenCalledTimes(invalidData.length);
    });

    test('blocks oversized JSON (DoS protection)', () => {
      // Create a JSON string larger than the max file size
      const largeObject = {
        data: 'x'.repeat(MAX_FILE_SIZE_BYTES + 1000), // Larger than limit
      };
      const largeJson = JSON.stringify(largeObject);

      expect(validateImportData(largeJson)).toBeNull();
      expect(mockToast.error).toHaveBeenCalledWith(
        'Import file too large (max 5MB)',
      );
    });

    test('blocks invalid input types', () => {
      const invalidInputs = [null, undefined, 123, true, {}, []];

      invalidInputs.forEach((input) => {
        expect(validateImportData(input as any)).toBeNull();
      });

      // These fail basic input validation, so no toast calls should be made
      expect(mockToast.error).not.toHaveBeenCalled();
    });

    test('blocks valid JSON with invalid export format', () => {
      const invalidFormatJson = JSON.stringify({
        someField: 'value',
        anotherField: 123,
        notAnExportFormat: true,
      });

      expect(validateImportData(invalidFormatJson)).toBeNull();
      expect(mockToast.error).toHaveBeenCalledWith(
        'Invalid import format. Please use a valid export file.',
      );
    });

    test('sanitizes nested prototype pollution attempts', () => {
      const nestedMaliciousJson = JSON.stringify({
        history: [
          {
            id: 'conv-1',
            name: 'Normal Conversation',
            messages: [],
            __proto__: { evil: true },
          },
        ],
        folders: [
          {
            name: 'Normal Folder',
            constructor: { prototype: { malicious: true } },
          },
        ],
      });

      const result = validateImportData(nestedMaliciousJson);
      expect(result).not.toBeNull();

      // Check that dangerous payloads were sanitized from nested objects
      if (
        result &&
        !Array.isArray(result) &&
        'history' in result &&
        'folders' in result
      ) {
        // Additional null checks for arrays
        if (
          result.history &&
          result.history.length > 0 &&
          result.folders &&
          result.folders.length > 0
        ) {
          // The malicious content should not be present
          const historyProto = Object.getPrototypeOf(result.history[0]);
          expect(historyProto).not.toHaveProperty('evil');

          // The constructor property exists naturally, but shouldn't contain our malicious payload
          expect(result.folders[0].constructor).not.toEqual({
            prototype: { malicious: true },
          });

          // Check that safe data remains
          expect(result.history[0].name).toBe('Normal Conversation');
          expect(result.folders[0].name).toBe('Normal Folder');
        }
      }
    });
  });
});

/**
 * URL Validation Tests
 *
 * Tests for Media URL, OAuth URL, and Path Normalization validation.
 * HTTP/WebSocket path validation is handled server-side in the proxy layer.
 */
import { isValidMediaURL } from '@/utils/media/validation';
import { isValidConsentPromptURL } from '@/utils/security/oauth-validation';

const {
  validateProxyHttpPath,
} = require('../../utils/security/url-validation');

describe('URL Validation Tests', () => {
  const originalEnv = process.env.NODE_ENV;

  beforeAll(() => {
    // @ts-ignore - Modifying NODE_ENV for test purposes
    process.env.NODE_ENV = 'development';
  });

  afterAll(() => {
    // @ts-ignore - Restoring NODE_ENV after test
    process.env.NODE_ENV = originalEnv;
  });

  // ============================================================================
  // MEDIA URL VALIDATION
  // ============================================================================
  describe('Media URL Validation', () => {
    describe('Positive Tests - Valid media URLs should pass', () => {
      it('accepts valid HTTPS image URLs', () => {
        const validUrls = [
          'https://cdn.example.com/image.jpg',
          'https://images.unsplash.com/photo.png',
          'https://static.website.com/video.mp4',
          'https://media.company.org/assets/logo.svg',
          // truncated
          'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUA',
          'data:image/jpeg;base64,iVBORw0KGgoAAAANSUhEUgAABXg',
        ];

        validUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(true);
        });
      });

      it('accepts valid HTTP media URLs', () => {
        expect(isValidMediaURL('http://example.com/image.jpg')).toBe(true);
        expect(isValidMediaURL('http://media.site.com/video.webm')).toBe(true);
      });

      it('accepts localhost URLs for development environments', () => {
        const devUrls = [
          'http://localhost/image.jpg',
          'https://localhost:3000/video.mp4',
          'http://127.0.0.1:8080/media.png',
          'https://127.1.1.1:5000/asset.gif',
          'http://[::1]:3000/image.jpg',
        ];

        devUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(true);
        });
      });
    });

    describe('Negative Tests - Invalid URLs should be blocked', () => {
      it('blocks dangerous protocol schemes', () => {
        const dangerousUrls = [
          'javascript:alert("xss")',
          'data:image/svg+xml,<svg><script>alert("xss")</script></svg>',
          'data:image/svg+xml,<svg><SCRIPT>alert("xss")</SCRIPT></svg>',
          'data:image/svg+xml,<svg onload="alert(1)"></svg>',
          // temorary, add to allowed list when we add support for SVG
          'data:image/svg+xml,<svg><text>Hello World</text></svg>',
          'file:///etc/passwd',
          'ftp://evil.com/image.jpg',
        ];

        dangerousUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(false);
        });
      });

      it('blocks URLs with embedded credentials', () => {
        const credentialUrls = [
          'https://user:password@example.com/image.jpg',
          'http://admin:secret@cdn.com/video.mp4',
        ];

        credentialUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(false);
        });
      });

      it('blocks reserved IP ranges to prevent SSRF', () => {
        const ssrfUrls = [
          'http://0.0.0.0/image.jpg',
          'https://224.0.0.1/video.mp4', // Multicast
          'http://240.1.1.1/media.png', // Multicast
          'https://255.255.255.255/image.gif', // Broadcast
        ];

        ssrfUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(false);
        });
      });

      it('blocks malformed and empty URLs', () => {
        const invalidUrls = [
          '',
          'not-a-url',
          'ht tp://broken.com/image.jpg',
          '://no-protocol.com/video.mp4',
          null,
          undefined,
          123,
        ];

        invalidUrls.forEach((url) => {
          expect(isValidMediaURL(url as any)).toBe(false);
        });
      });

      it('blocks URLs with control characters', () => {
        const controlCharUrls = [
          'https://example.com\x00/image.jpg',
          'https://example.com\x0a/video.mp4',
          'https://example.com\x0d/media.png',
          'https://example.com\x7f/image.gif',
        ];

        controlCharUrls.forEach((url) => {
          expect(isValidMediaURL(url)).toBe(false);
        });
      });
    });
  });

  // ============================================================================
  // OAUTH URL VALIDATION
  // ============================================================================
  describe('OAuth URL Validation', () => {
    describe('Positive Tests - Valid URLs should pass', () => {
      it('accepts valid HTTPS OAuth URLs', () => {
        const validUrls = [
          'https://accounts.google.com/oauth/authorize',
          'https://login.microsoftonline.com/oauth2/authorize',
          'https://github.com/login/oauth/authorize',
          'https://api.example.com/oauth/consent',
        ];

        validUrls.forEach((url) => {
          expect(isValidConsentPromptURL(url)).toBe(true);
        });
      });

      it('accepts valid HTTP URLs', () => {
        expect(isValidConsentPromptURL('http://example.com/oauth')).toBe(true);
      });
    });

    describe('Negative Tests - Invalid URLs should be blocked', () => {
      it('blocks dangerous protocol schemes', () => {
        const dangerousUrls = [
          'javascript:alert("xss")',
          'data:text/html,<script>alert("xss")</script>',
          'vbscript:msgbox("xss")',
          'file:///etc/passwd',
          'ftp://evil.com/malware',
        ];

        dangerousUrls.forEach((url) => {
          expect(isValidConsentPromptURL(url)).toBe(false);
        });
      });

      it('blocks URLs with embedded credentials', () => {
        const credentialUrls = [
          'https://user:password@example.com/oauth',
          'http://admin:secret@malicious.com',
          'https://attacker:token@legitimate-site.com/oauth',
        ];

        credentialUrls.forEach((url) => {
          expect(isValidConsentPromptURL(url)).toBe(false);
        });
      });

      it('blocks malformed URLs', () => {
        const malformedUrls = [
          '',
          'not-a-url',
          'ht tp://broken.com',
          '://no-protocol.com',
          null,
          undefined,
        ];

        malformedUrls.forEach((url) => {
          expect(isValidConsentPromptURL(url as any)).toBe(false);
        });
      });

      it('blocks URLs with control characters', () => {
        const controlCharUrls = [
          'https://example.com /oauth', // space character
          'https://example.com\t/oauth', // tab character
          'https://example.com\n/oauth', // newline character
          'https://example.com\r/oauth', // carriage return
        ];

        controlCharUrls.forEach((url) => {
          expect(isValidConsentPromptURL(url)).toBe(false);
        });
      });
    });
  });

  // ============================================================================
  // PATH NORMALIZATION TESTS
  // ============================================================================
  describe('Path Normalization Tests', () => {
    describe('Path Traversal Prevention', () => {
      it('should block simple path traversal', () => {
        const result = validateProxyHttpPath('/api/../admin');
        expect(result.isValid).toBe(false);
      });

      it('should block encoded path traversal', () => {
        const result = validateProxyHttpPath('/api/%2E%2E/admin');
        expect(result.isValid).toBe(false);
      });

      it('should block double-encoded path traversal', () => {
        const result = validateProxyHttpPath('/api/%252E%252E%252Fadmin');
        expect(result.isValid).toBe(false);
      });

      it('should block complex traversal attempts', () => {
        const result = validateProxyHttpPath('/api/chat/../../admin');
        expect(result.isValid).toBe(false);
      });
    });

    describe('Valid Paths', () => {
      it('should allow valid paths', () => {
        const result = validateProxyHttpPath('/api/chat/stream');
        expect(result.isValid).toBe(true);
      });

      it('should normalize and allow paths with dots', () => {
        const result = validateProxyHttpPath('/api/./chat/stream');
        expect(result.isValid).toBe(true);
      });

      it('should handle query parameters', () => {
        const result = validateProxyHttpPath('/api/chat/stream?session=123');
        expect(result.isValid).toBe(true);
      });
    });

    describe('Edge Cases', () => {
      it('should reject empty path', () => {
        const result = validateProxyHttpPath('');
        expect(result.isValid).toBe(false);
      });

      it('should reject non-string input', () => {
        const result = validateProxyHttpPath(null as any);
        expect(result.isValid).toBe(false);
      });
    });
  });
});

/**
 * Consolidated tests for InteractionModal component, OAuth flows, and human-in-the-loop functionality
 *
 * Tests cover:
 * - InteractionModal component rendering and behavior (text, binary choice, radio, notification types)
 * - OAuth flow integration (popup windows, event listeners, completion handling)
 * - User interaction response handling and WebSocket communication
 * - Error handling (malformed messages, popup blocking, concurrent interactions)
 */

import {
  render,
  screen,
  fireEvent,
  waitFor,
  act,
} from '@testing-library/react';
import React from 'react';

import {
  isSystemInteractionMessage,
  isOAuthConsentMessage,
  extractOAuthUrl,
} from '@/types/websocket';
import { InteractionModal } from '@/components/Chat/ChatInteractionMessage';

// Mock react-hot-toast
jest.mock('react-hot-toast', () => {
  const mockToastFunctions = {
    success: jest.fn(),
    error: jest.fn(),
    loading: jest.fn(),
    dismiss: jest.fn(),
    custom: jest.fn(),
  };

  return {
    __esModule: true,
    default: mockToastFunctions,
    toast: mockToastFunctions,
  };
});

// Mock window.open for OAuth tests
const mockWindowOpen = jest.fn();
const mockAddEventListener = jest.fn();
const mockRemoveEventListener = jest.fn();

Object.defineProperty(window, 'open', {
  value: mockWindowOpen,
  writable: true,
});

Object.defineProperty(window, 'addEventListener', {
  value: mockAddEventListener,
  writable: true,
});

Object.defineProperty(window, 'removeEventListener', {
  value: mockRemoveEventListener,
  writable: true,
});

describe('InteractionModal and Human-in-the-Loop Functionality', () => {
  const mockOnClose = jest.fn();
  const mockOnSubmit = jest.fn();

  // Get the mocked toast object
  const mockToast = require('react-hot-toast').toast;

  beforeEach(() => {
    jest.clearAllMocks();
  });

  // ============================================================================
  // OAUTH FLOW INTEGRATION TESTS
  // ============================================================================
  describe('OAuth Flow Integration', () => {
    /**
     * Description: Verifies that OAuth consent messages trigger opening a new browser tab with the correct authorization URL
     * Success: window.open is called with the extracted OAuth URL and appropriate target parameters
     */
    test('OAuth message opens new tab with correct URL', () => {
      const handleWebSocketMessage = (message: any) => {
        if (
          isSystemInteractionMessage(message) &&
          message.content?.input_type === 'oauth_consent'
        ) {
          const oauthUrl = extractOAuthUrl(message);
          if (oauthUrl) {
            window.open(oauthUrl, '_blank');
          }
        }
      };

      const oauthMessage = {
        type: 'system_interaction_message',
        conversation_id: 'test-conv',
        content: {
          input_type: 'oauth_consent',
          oauth_url:
            'https://oauth.provider.com/authorize?state=xyz&client_id=123',
        },
      };

      handleWebSocketMessage(oauthMessage);

      expect(mockWindowOpen).toHaveBeenCalledWith(
        'https://oauth.provider.com/authorize?state=xyz&client_id=123',
        '_blank',
      );
    });

    /**
     * Description: Verifies that OAuth flow establishes message event listeners for completion detection
     * Success: Event listeners are set up to detect OAuth completion messages from popup windows
     */
    test('OAuth flow sets up completion event listener', () => {
      const handleOAuthConsent = (message: any) => {
        if (isOAuthConsentMessage(message)) {
          const oauthUrl = extractOAuthUrl(message);
          if (oauthUrl) {
            const popup = window.open(
              oauthUrl,
              'oauth-popup',
              'width=600,height=700',
            );

            const handleOAuthComplete = (event: MessageEvent) => {
              if (popup && !popup.closed) popup.close();
              window.removeEventListener('message', handleOAuthComplete);
            };

            window.addEventListener('message', handleOAuthComplete);
          }
        }
      };

      const oauthMessage = {
        type: 'system_interaction_message',
        content: {
          input_type: 'oauth_consent',
          oauth_url: 'https://oauth.example.com/authorize',
        },
      };

      handleOAuthConsent(oauthMessage);

      expect(mockWindowOpen).toHaveBeenCalledWith(
        'https://oauth.example.com/authorize',
        'oauth-popup',
        'width=600,height=700',
      );
      expect(mockAddEventListener).toHaveBeenCalledWith(
        'message',
        expect.any(Function),
      );
    });

    /**
     * Description: Verifies that OAuth popup windows are properly closed and cleaned up after completion
     * Success: Event listeners are removed and popup windows are closed when OAuth flow completes
     */
    test('OAuth popup cleanup on completion', () => {
      let eventHandler: (event: MessageEvent) => void;

      mockAddEventListener.mockImplementation((event, handler) => {
        if (event === 'message') {
          eventHandler = handler;
        }
      });

      const mockPopup = {
        closed: false,
        close: jest.fn(),
      };

      mockWindowOpen.mockReturnValue(mockPopup);

      const handleOAuthConsent = (message: any) => {
        if (isOAuthConsentMessage(message)) {
          const oauthUrl = extractOAuthUrl(message);
          if (oauthUrl) {
            const popup = window.open(
              oauthUrl,
              'oauth-popup',
              'width=600,height=700',
            );

            const handleOAuthComplete = (event: MessageEvent) => {
              if (popup && !popup.closed) popup.close();
              window.removeEventListener('message', handleOAuthComplete);
            };

            window.addEventListener('message', handleOAuthComplete);
          }
        }
      };

      const oauthMessage = {
        type: 'system_interaction_message',
        content: {
          input_type: 'oauth_consent',
          oauth_url: 'https://oauth.example.com/authorize',
        },
      };

      handleOAuthConsent(oauthMessage);

      // Simulate OAuth completion message
      const completionEvent = new MessageEvent('message', {
        data: { type: 'oauth_complete', success: true },
      });

      eventHandler(completionEvent);

      expect(mockPopup.close).toHaveBeenCalled();
      expect(mockRemoveEventListener).toHaveBeenCalledWith(
        'message',
        expect.any(Function),
      );
    });

    /**
     * Description: Verifies that OAuth popup blocking by browsers is handled gracefully with fallback options
     * Success: Popup blocking is detected, appropriate error messages shown, fallback authentication methods offered
     */
    test('handles OAuth popup blocking gracefully', () => {
      // Mock popup being blocked (window.open returns null)
      mockWindowOpen.mockReturnValue(null);

      const handleOAuthConsent = (message: any) => {
        if (isOAuthConsentMessage(message)) {
          const oauthUrl = extractOAuthUrl(message);
          if (oauthUrl) {
            const popup = window.open(oauthUrl, '_blank');
            if (!popup) {
              console.warn('Popup blocked - please allow popups for OAuth');
              return false;
            }
            return true;
          }
        }
        return false;
      };

      const oauthMessage = {
        type: 'system_interaction_message',
        content: {
          input_type: 'oauth_consent',
          oauth_url: 'https://oauth.example.com/authorize',
        },
      };

      const consoleWarn = jest.spyOn(console, 'warn').mockImplementation();

      const result = handleOAuthConsent(oauthMessage);

      expect(result).toBe(false);
      expect(consoleWarn).toHaveBeenCalledWith(
        'Popup blocked - please allow popups for OAuth',
      );

      consoleWarn.mockRestore();
    });
  });

  // ============================================================================
  // INTERACTION MODAL COMPONENT TESTS
  // ============================================================================
  describe('InteractionModal Component - Text Input Type', () => {
    it('should render text input with placeholder', () => {
      const message = {
        type: 'system_interaction_message',
        content: {
          input_type: 'text',
          text: 'Please enter your name:',
          placeholder: 'Your full name here',
          required: true,
        },
      };

      render(
        <InteractionModal
          isOpen={true}
          interactionMessage={message}
          onClose={mockOnClose}
          onSubmit={mockOnSubmit}
        />,
      );

      expect(screen.getByText('Please enter your name:')).toBeInTheDocument();
      expect(
        screen.getByPlaceholderText('Your full name here'),
      ).toBeInTheDocument();
      expect(
        screen.getByRole('button', { name: 'Submit' }),
      ).toBeInTheDocument();
      expect(
        screen.queryByRole('button', { name: 'Cancel' }),
      ).not.toBeInTheDocument();
    });

    it('should handle text input submission', async () => {
      const message = {
        type: 'system_interaction_message',
        content: {
          input_type: 'text',
          text: 'Enter feedback:',
          required: false,
        },
      };

      render(
        <InteractionModal
          isOpen={true}
          interactionMessage={message}
          onClose={mockOnClose}
          onSubmit={mockOnSubmit}
        />,
      );

      const textarea = screen.getByRole('textbox');
      const submitButton = screen.getByRole('button', { name: 'Submit' });

      fireEvent.change(textarea, { target: { value: 'Great app!' } });
      fireEvent.click(submitButton);

      expect(mockOnSubmit).toHaveBeenCalledWith({
        interactionMessage: message,
        userResponse: 'Great app!',
      });
      expect(mockOnClose).toHaveBeenCalled();
    });

    it('should validate required text input', async () => {
      const message = {
        type: 'system_interaction_message',
        content: {
          input_type: 'text',
          text: 'Required field:',
          required: true,
        },
      };

      render(
        <InteractionModal
          isOpen={true}
          interactionMessage={message}
          onClose={mockOnClose}
          onSubmit={mockOnSubmit}
        />,
      );

      const submitButton = screen.getByRole('button', { name: 'Submit' });
      fireEvent.click(submitButton);

      expect(screen.getByText('This field is required.')).toBeInTheDocument();
      expect(mockOnSubmit).not.toHaveBeenCalled();
