    /**
     * Description: Verifies that multiple simultaneous interaction messages are handled correctly without conflicts
     * Success: Concurrent interactions are queued or managed appropriately, no data corruption or UI conflicts occur
     */
    test('handles concurrent interaction messages', () => {
      let activeInteraction: any = null;
      const interactionQueue: any[] = [];

      const handleWebSocketMessage = (message: any) => {
        if (
          isSystemInteractionMessage(message) &&
          message.content?.input_type !== 'oauth_consent'
        ) {
          if (activeInteraction) {
            interactionQueue.push(message);
          } else {
            activeInteraction = message;
          }
        }
      };

      const completeInteraction = () => {
        activeInteraction = null;

        if (interactionQueue.length > 0) {
          activeInteraction = interactionQueue.shift();
        }
      };

      // Send multiple interactions
      const interactions = [
        {
          type: 'system_interaction_message',
          id: '1',
          content: { input_type: 'user_confirmation', text: 'First' },
        },
        {
          type: 'system_interaction_message',
          id: '2',
          content: { input_type: 'user_confirmation', text: 'Second' },
        },
        {
          type: 'system_interaction_message',
          id: '3',
          content: { input_type: 'user_confirmation', text: 'Third' },
        },
      ];

      interactions.forEach(handleWebSocketMessage);

      expect(activeInteraction.id).toBe('1');
      expect(interactionQueue).toHaveLength(2);

      completeInteraction();
      expect(activeInteraction.id).toBe('2');
      expect(interactionQueue).toHaveLength(1);

      completeInteraction();
      expect(activeInteraction.id).toBe('3');
      expect(interactionQueue).toHaveLength(0);
    });
  });
});

const {
  ALLOWED_PATHS,
  HTTP_PROXY_PATH,
  WEBSOCKET_PROXY_PATH,
} = require('../../constants');

/**
 * @typedef {Object} ValidationResult
 * @property {boolean} isValid
 * @property {string} [error]
 */

/**
 * SSRF Prevention: Validates HTTP proxy paths
 *
 * Ensures incoming requests only access allowed backend endpoints.
 * Uses URL constructor for safe normalization of:
 * - Percent-encoding/decoding
 * - Duplicate slashes
 * - Dot-segments (., ..)
 * - Path traversal attempts
 *
 * @param {string} pathname - The full pathname from the request (e.g., '/api/chat/stream')
 * @returns {ValidationResult} Validation result with error message if invalid
 */
function validateProxyHttpPath(pathname) {
  if (typeof pathname !== 'string' || pathname.length === 0) {
    return {
      isValid: false,
      error: 'Path must be a non-empty string',
    };
  }

  // Use URL constructor to safely normalize the path
  let normalizedPath;
  try {
    const url = new URL(pathname, 'http://localhost');
    normalizedPath = url.pathname;
  } catch (_err) {
    return {
      isValid: false,
      error: 'Invalid or malformed path',
    };
  }

  // Must start with /api/
  if (!normalizedPath.startsWith(HTTP_PROXY_PATH + '/')) {
    return {
      isValid: false,
      error: `Path must start with ${HTTP_PROXY_PATH}/`,
    };
  }

  // Strip /api prefix to get backend path
  const backendPath = normalizedPath.substring(HTTP_PROXY_PATH.length);

  // Detect any remaining traversal attempts (shouldn't happen after URL normalization, but defense in depth)
  if (backendPath.includes('..')) {
    return {
      isValid: false,
      error: 'Path traversal is not allowed',
    };
  }

  // Check against allowlist
  const isAllowed = ALLOWED_PATHS.some(
    (allowed) =>
      backendPath === allowed || backendPath.startsWith(allowed + '/'),
  );

  if (!isAllowed) {
    return {
      isValid: false,
      error: `Backend path '${backendPath}' is not in allowed list`,
    };
  }

  return { isValid: true };
}

/**
 * SSRF Prevention: Validates WebSocket proxy path
 *
 * Ensures WebSocket connections only use the allowed endpoint.
 * Used by proxy server to prevent unauthorized WebSocket access.
 *
 * @param {string} pathname - The pathname from the WebSocket upgrade request
 * @returns {ValidationResult} Validation result with error message if invalid
 */
function validateProxyWebSocketPath(pathname) {
  if (pathname !== WEBSOCKET_PROXY_PATH) {
    return {
      isValid: false,
      error: `WebSocket path '${pathname}' is not allowed. Expected: ${WEBSOCKET_PROXY_PATH}`,
    };
  }

  return { isValid: true };
}

/**
 * SSRF Prevention: Validates backend URLs
 *
 * Ensures server-side fetch requests only target safe URLs.
 * Use this before making any fetch() calls in API routes.
 *
 * @param {string} url - The URL to validate
 * @returns {ValidationResult} Validation result with error message if invalid
 */
function validateBackendUrl(url) {
  let parsedUrl;

  try {
    parsedUrl = new URL(url);
  } catch (_err) {
    return {
      isValid: false,
      error: 'Invalid URL format',
    };
  }

  // Only allow http/https protocols
  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
    return {
      isValid: false,
      error: `Protocol '${parsedUrl.protocol}' is not allowed. Use http or https.`,
    };
  }

  return { isValid: true };
}

module.exports = {
  validateProxyHttpPath,
  validateProxyWebSocketPath,
  validateBackendUrl,
};

import toast from 'react-hot-toast';

import { SupportedExportFormats } from '@/types/export';
import { MAX_FILE_SIZE_BYTES } from '@/constants';

/**
 * Validates and sanitizes imported JSON data to prevent XSS and prototype pollution
 * @param rawJson - Raw JSON string from file
 * @returns Validated export format or null if invalid
 */
export function validateImportData(
  rawJson: string,
): SupportedExportFormats | null {
  // Basic input validation
  if (!rawJson || typeof rawJson !== 'string') {
    return null;
  }

  // Simple DoS protection - limit JSON string length
  if (rawJson.length > MAX_FILE_SIZE_BYTES) {
    const maxSizeMB = Math.round(MAX_FILE_SIZE_BYTES / (1024 * 1024));
    toast.error(`Import file too large (max ${maxSizeMB}MB)`);
    return null;
  }

  let parsed: any;
  try {
    // Parse JSON safely
    parsed = JSON.parse(rawJson);
  } catch (_error) {
    toast.error('Invalid JSON format');
    return null;
  }

  // Block null or non-object data
  if (parsed === null || typeof parsed !== 'object') {
    toast.error('Import data must be a valid object');
    return null;
  }

  // Prevent prototype pollution by blocking dangerous properties
  const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
  function sanitizeObject(obj: any): any {
    if (obj === null || typeof obj !== 'object') return obj;

    if (Array.isArray(obj)) {
      return obj.map((item) => sanitizeObject(item));
    }

    const sanitized: any = {};
    for (const [key, value] of Object.entries(obj)) {
      // Block dangerous prototype pollution keys
      if (dangerousKeys.includes(key)) {
        console.warn(`Blocked dangerous key during import: ${key}`);
        continue;
      }

      // Recursively sanitize nested objects
      sanitized[key] = sanitizeObject(value);
    }
    return sanitized;
  }

  // Sanitize the parsed data
  const sanitized = sanitizeObject(parsed);

  // Validate export format structure
  if (Array.isArray(sanitized)) {
    // ExportFormatV1 - array of conversations
    if (
      sanitized.every(
        (item) =>
          typeof item === 'object' &&
          item !== null &&
          typeof item.id === 'number' &&
          typeof item.name === 'string' &&
          Array.isArray(item.messages),
      )
    ) {
      return sanitized as SupportedExportFormats;
    }
  } else if (typeof sanitized === 'object' && sanitized !== null) {
    // Check for V2, V3, V4 formats
    if (
      sanitized.version === 4 &&
      Array.isArray(sanitized.history) &&
      Array.isArray(sanitized.folders) &&
      Array.isArray(sanitized.prompts)
    ) {
      return sanitized as SupportedExportFormats;
    }

    if (
      sanitized.version === 3 &&
      Array.isArray(sanitized.history) &&
      Array.isArray(sanitized.folders)
    ) {
      return sanitized as SupportedExportFormats;
    }

    // V2 format (history and folders properties)
    if (
      (sanitized.history === null || Array.isArray(sanitized.history)) &&
      (sanitized.folders === null || Array.isArray(sanitized.folders))
    ) {
      return sanitized as SupportedExportFormats;
    }
  }

  toast.error('Invalid import format. Please use a valid export file.');
  return null;
}

/**
 * OAuth URL validation to prevent open redirect attacks
 * @param raw - URL to validate
 * @returns boolean indicating if URL is safe for OAuth redirects
 */
export function isValidConsentPromptURL(raw: string): boolean {
  // 1) quick reject: control chars or whitespace that can confuse parsers/logs
  //    (CR, LF, TAB, VT, FF, and space)
  if (/[ \t\r\n\v\f]/.test(raw)) return false;

  // 2) must be absolute & parseable
  let u: URL;
  try {
    u = new URL(raw);
  } catch {
    return false;
  }

  // 3) protocol: only http(s)
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return false;

  // 4) forbid embedded credentials (userinfo)
  if (u.username || u.password) return false;

  // 5) optional: cap length to reduce abuse surface
  if (raw.length > 8192) return false;

  return true;
}

export interface ValidationResult {
  isValid: boolean;
  error?: string;
}

/**
 * SSRF Prevention: Validates HTTP proxy paths
 */
export function validateProxyHttpPath(_pathname: string): ValidationResult;

/**
 * SSRF Prevention: Validates WebSocket proxy path
 */
export function validateProxyWebSocketPath(_pathname: string): ValidationResult;

/**
 * SSRF Prevention: Validates backend URLs
 */
export function validateBackendUrl(_url: string): ValidationResult;

